    def _process_chunk_with_retry(
        self,
        chunk_path: Path,
        deck_name: str,
        pdf_output_path: Path,
        request: GenerateFlashcardsRequest,
        chunk_index: int,
        total_chunks: int,
    ) -> Deck | None:
        """Process chunk with exponential backoff retry on rate limit errors."""
        delay = float(CHUNK_RETRY_INITIAL_DELAY)
        self._last_chunk_error_message = None

        for attempt in range(1, CHUNK_RETRY_MAX_ATTEMPTS + 1):
            try:
                result = self._process_chunk_internal(
                    chunk_path,
                    deck_name,
                    pdf_output_path,
                    request,
                    chunk_index,
                    total_chunks,
                )
                if result is not None:
                    self._last_chunk_error_message = None
                    return result

                if attempt < CHUNK_RETRY_MAX_ATTEMPTS:
                    logger.warning(
                        f"Chunk {chunk_index}/{total_chunks}: "
                        f"retry {attempt}/{CHUNK_RETRY_MAX_ATTEMPTS} in {delay}s..."
                    )
                    time.sleep(delay)
                    delay = min(
                        delay * CHUNK_RETRY_BACKOFF_MULTIPLIER,
                        CHUNK_RETRY_MAX_DELAY,
                    )
                else:
                    self._last_chunk_error_message = (
                        "Chunk processing returned no result after retries"
                    )

            except (OSError, RuntimeError) as e:
                self._last_chunk_error_message = str(e)
                error_msg = str(e).lower()
                is_rate_limit = any(
                    pattern in error_msg
                    for pattern in [
                        "rpc create_artifact",
                        "rate limit",
                        "generation_failed",
                    ]
                )
                is_transient = isinstance(e, OSError) or is_rate_limit

                if is_transient and attempt < CHUNK_RETRY_MAX_ATTEMPTS:
                    logger.warning(
                        f"Chunk {chunk_index}/{total_chunks}: "
                        f"transient error, retry {attempt}/{CHUNK_RETRY_MAX_ATTEMPTS} "
                        f"in {delay}s..."
                    )
                    time.sleep(delay)
                    delay = min(
                        delay * CHUNK_RETRY_BACKOFF_MULTIPLIER,
                        CHUNK_RETRY_MAX_DELAY,
                    )
                else:
                    logger.error(f"Chunk {chunk_index}/{total_chunks}: {e}")
                    return None

        return None

