        max_pairs = max(self.MAX_SIMILAR_PAIRS, 0)
        similar_pairs: dict[tuple[int, int], float] = {
            pair: 1.0 for pair in sorted(exact_pairs)[:max_pairs]
        }
        truncated = len(exact_pairs) > max_pairs

